#!/usr/bin/env bash
# Gecko template build (Phase 1): the production WebView template's
# feature set ported to GeckoView 159, on the Phase-0 device-proven
# engine recipe (see gecko-spike/DEBUG-REPORT.md rounds 1-4):
#   * GeckoView 159 + the COMPLETE POM dependency bundle in
#     gecko-spike/deps/extra-diag (incl. androidx.arch.core
#     core-runtime/core-common 2.2.0 and androidx.core core-viewtree
#     1.0.0);
#   * library R classes generated by aapt2 link --java
#     --extra-packages for androidx.core, androidx.core.viewtree,
#     androidx.startup, androidx.lifecycle.runtime,
#     org.mozilla.geckoview (without these, androidx.startup's
#     InitializationProvider dies before any UI);
#   * merged GeckoView AAR manifest + lifecycle-process
#     InitializationProvider, extractNativeLibs="true", arm64-v8a;
#   * dexing via standalone R8 9.5.29 in D8 mode (build-tools 34's d8
#     NPEs on the bundled jars' Kotlin metadata).
# Template v2 (Phase 3) adds the Phase-2 device-proven UnifiedPush
# push stack, productized (see gecko-push/PUSH-TEST-REPORT.md and
# PORT-REPORT.md "Template v2"):
#   * org.unifiedpush.android:connector 3.3.5 AAR (deps reused from
#     gecko-push/deps): classes.jar dexed, manifest merged (WAKE_LOCK,
#     <queries>, RaiseToForegroundService, LinkActivity,
#     MessagingReceiverImpl), res compiled, R class generated via
#     --extra-packages org.unifiedpush.android.connector;
#   * com.google.crypto.tink:tink 1.23.0 jar dexed (connector's
#     vendored fixed_webpush decrypt path needs tink subtle classes);
#   * multi-dex packaging: zip classes*.dex (push jars push the build
#     past the single-dex limit; zipping only classes.dex would
#     silently drop classes2.dex).
# Template v3 (Phase 5) changes ONE thing vs v2: distributor
# preference in PushBridge.ensureDistributor — when the Aprica Push
# generator app (package app.webgen.generator.push) is installed as
# a UnifiedPush distributor, it is saved as the current distributor
# (UnifiedPush.saveDistributor, connector 3.3.5) before register;
# otherwise the v2 current/default flow runs unchanged.
# Output: ~/workspace/web2apk/gecko-template/gecko-template.apk
# (package app.webgen.geckotemplate, templateVersion 3 — the patcher
# turns this into stand-alone site apps)
set -euo pipefail

ROOT="$HOME/workspace/web2apk"
GT="$ROOT/gecko-template"
SPIKE="$ROOT/gecko-spike"
PUSH="$ROOT/gecko-push"
TOOLS="$ROOT/tools"
export JAVA_HOME="$TOOLS/jdk"
export PATH="$JAVA_HOME/bin:$TOOLS/kotlinc/bin:$PATH"

ANDROID_JAR="$TOOLS/sdk/platforms/android-34/android.jar"
BT="$TOOLS/sdk/build-tools/34.0.0"
APP="$GT/app"
GV="$SPIKE/deps/gv"          # extracted geckoview AAR
DL="$SPIKE/deps/downloads-diag"
WORK="$GT/build"
KS="$ROOT/test-keystore-TEST-ONLY.jks"
# Same password contract as build_template.sh (env var, with the same
# default the template script carries). Never echo this value.
if [ -z "${WEB2APK_KS_PASS:-}" ]; then
  WEB2APK_KS_PASS=$(sed -n 's/.*WEB2APK_KS_PASS:-\([^}]*\)}.*/\1/p' "$ROOT/build_template.sh" | head -1)
fi
KS_PASS="${WEB2APK_KS_PASS:?could not determine keystore password}"
ABI="arm64-v8a"
LP_AAR="$DL/lifecycle-process-2.11.0.aar"
UP_DIR="$PUSH/deps/up"
UP_JAR="$UP_DIR/x/classes.jar"
UP_AAR="$UP_DIR/connector-3.3.5.aar"
TINK_JAR="$PUSH/deps/tink-1.23.0.jar"
APP_ID="app.webgen.geckotemplate"

rm -rf "$WORK"
mkdir -p "$WORK/compiled" "$WORK/classes" "$WORK/rclasses" "$WORK/dex" "$WORK/assets" "$WORK/lib/$ABI" "$WORK/aar" "$WORK/gen"

echo "== 0. merge manifests: GeckoView AAR + lifecycle provider + UnifiedPush AAR =="
python3 - "$GV/AndroidManifest.xml" "$APP/src/main/AndroidManifest.xml" \
        "$WORK/AndroidManifest.xml" "$APP_ID" "$LP_AAR" "$UP_AAR" <<'PYEOF'
import re, sys, zipfile
gv_path, app_path, out_path, app_id, lp_aar, up_aar = sys.argv[1:7]
gv = open(gv_path, encoding="utf-8").read()
app = open(app_path, encoding="utf-8").read()
up = zipfile.ZipFile(up_aar).read("AndroidManifest.xml").decode("utf-8")

def sub(s):
    s = s.replace("${applicationId}", app_id)
    return re.sub(r'\s+tools:[A-Za-z]+="[^"]*"', "", s)

def app_children(manifest):
    m = re.search(r"<application[^>]*>(.*)</application>", manifest, re.S)
    return m.group(1) if m else ""

existing = set(re.findall(r'android:name="([^"]+)"', app))
merged = []
for src in (gv, up):
    for tag in re.findall(r"<uses-permission[^>]*/>", src) + \
               re.findall(r"<uses-feature[^>]*/>", src):
        m2 = re.search(r'android:name="([^"]+)"', tag)
        name = m2.group(1) if m2 else tag
        if name not in existing:
            merged.append(sub(tag))
            existing.add(name)

# UnifiedPush <queries> (distributor discovery on Android 11+).
qm = re.search(r"<queries>.*?</queries>", up, re.S)
queries = sub(qm.group(0)) if qm else ""
print("UP queries merged:", "yes" if queries else "NO - NOT FOUND")

# lifecycle-process: splice its InitializationProvider (AGP would merge
# it; ProcessLifecycleOwner.get() fails without it).
lp_manifest = zipfile.ZipFile(lp_aar).read("AndroidManifest.xml").decode("utf-8")
pm = re.search(r"<provider\b.*?</provider>", lp_manifest, re.S)
provider = sub(pm.group(0)) if pm else ""
print("lifecycle provider merged:", "yes" if provider else "NO - NOT FOUND")

children = sub(app_children(gv)) + "\n    " + provider + "\n    " + sub(app_children(up))

out = app.replace("<application",
                  "\n    ".join(merged) +
                  ("\n    " + queries if queries else "") +
                  "\n    <application", 1)
out = out.replace("</application>", children + "\n    </application>", 1)
open(out_path, "w", encoding="utf-8").write(out)
print(f"merged {len(merged)} uses-* entries + queries + AAR children + provider")
PYEOF

echo "== 1. aapt2 compile resources (app + geckoview + R-referencing AARs) =="
"$BT/aapt2" compile --dir "$APP/src/main/res" -o "$WORK/compiled/res.zip"
"$BT/aapt2" compile --dir "$GV/res" -o "$WORK/compiled/gv-res.zip"
# AARs whose bundled code references its own R classes (audit in
# DEBUG-REPORT.md round 3). Their res must be part of the link so the
# generated R fields carry the final linked IDs.
for pair in core-1.19.1:core startup-runtime-1.2.0:startup \
            lifecycle-runtime-android-2.11.0:lifecycle \
            core-viewtree-1.0.0:viewtree; do
  aar="${pair%%:*}"; name="${pair##*:}"
  mkdir -p "$WORK/aar/$name"
  (cd "$WORK/aar/$name" && unzip -qo "$DL/$aar.aar" 'res/*')
  "$BT/aapt2" compile --dir "$WORK/aar/$name/res" -o "$WORK/compiled/$name-res.zip"
  echo "compiled AAR res: $aar"
done
mkdir -p "$WORK/aar/up"
(cd "$WORK/aar/up" && unzip -qo "$UP_AAR" 'res/*')
"$BT/aapt2" compile --dir "$WORK/aar/up/res" -o "$WORK/compiled/up-res.zip"
echo "compiled AAR res: connector-3.3.5"

echo "== 2. merge assets (app assets incl. webext + geckoview omni.ja) =="
cp -r "$APP/src/main/assets/." "$WORK/assets/"
cp "$GV/assets/omni.ja" "$WORK/assets/"

echo "== 3. aapt2 link (with R generation for library packages) =="
"$BT/aapt2" link \
  -o "$WORK/unsigned.apk" \
  -I "$ANDROID_JAR" \
  --manifest "$WORK/AndroidManifest.xml" \
  -A "$WORK/assets" \
  --min-sdk-version 26 --target-sdk-version 34 \
  --version-code 3 --version-name 3.0 \
  --auto-add-overlay \
  --java "$WORK/gen" \
  --output-text-symbols "$WORK/symbols.txt" \
  --extra-packages androidx.core:androidx.core.viewtree:androidx.startup:androidx.lifecycle.runtime:org.mozilla.geckoview:org.unifiedpush.android.connector \
  "$WORK/compiled/res.zip" "$WORK/compiled/gv-res.zip" \
  "$WORK/compiled/core-res.zip" "$WORK/compiled/startup-res.zip" \
  "$WORK/compiled/lifecycle-res.zip" "$WORK/compiled/viewtree-res.zip" \
  "$WORK/compiled/up-res.zip"
echo "generated R.java files:"
find "$WORK/gen" -name 'R.java' | sort

echo "== 4. kotlinc (no daemon) =="
kotlinc -J-Dkotlin.daemon.enabled=false \
  -Xskip-metadata-version-check \
  -classpath "$ANDROID_JAR:$GV/classes.jar:$UP_JAR:$TINK_JAR:$SPIKE/deps/extra-diag/core-1.19.1-classes.jar" \
  -d "$WORK/classes" \
  $(find "$APP/src/main/java" -name '*.kt')

echo "== 4b. javac the generated R.java files =="
"$JAVA_HOME/bin/javac" -source 8 -target 8 -nowarn \
  -cp "$ANDROID_JAR" \
  -d "$WORK/rclasses" \
  $(find "$WORK/gen" -name 'R.java')

echo "== 5. d8 -> classes.dex (app + R classes + geckoview + bundled POM deps) =="
# NOTE: build-tools 34's d8 (R8 8.2.2-dev) NPEs on the newer Kotlin
# metadata in these jars, so dexing uses a standalone newer
# R8 jar in D8 mode (same as the spike builds).
R8_JAR="$DL/r8-9.5.29.jar"
EXTRA_JARS=""
for j in "$SPIKE"/deps/extra-diag/*.jar; do [ -e "$j" ] && EXTRA_JARS="$EXTRA_JARS $j"; done
echo "extra dep jars:$EXTRA_JARS"
echo "push jars: $UP_JAR $TINK_JAR"
"$JAVA_HOME/bin/java" -cp "$R8_JAR" com.android.tools.r8.D8 \
  --lib "$ANDROID_JAR" \
  --min-api 26 \
  --output "$WORK/dex" \
  $(find "$WORK/classes" "$WORK/rclasses" -name '*.class') \
  "$GV/classes.jar" \
  $EXTRA_JARS \
  "$UP_JAR" "$TINK_JAR"

echo "== 6. add dex + native libs ($ABI), zipalign =="
cp "$GV/jni/$ABI/"*.so "$WORK/lib/$ABI/"
cp "$WORK/unsigned.apk" "$WORK/with-dex.apk"
# Multi-dex: tink + connector push the build past the single-dex
# limit, so zip ALL dex files (Phase-2 build incident: zipping only
# classes.dex silently dropped classes2.dex).
(cd "$WORK/dex" && zip -q "$WORK/with-dex.apk" classes*.dex)
ls -la "$WORK/dex"
(cd "$WORK" && zip -q with-dex.apk lib/$ABI/*.so)
"$BT/zipalign" -f 4 "$WORK/with-dex.apk" "$WORK/aligned.apk"

echo "== 7. apksigner sign (v1+v2, TEST keystore) =="
"$BT/apksigner" sign \
  --ks "$KS" --ks-pass "pass:$KS_PASS" --key-pass "pass:$KS_PASS" \
  --v1-signing-enabled true --v2-signing-enabled true \
  --out "$GT/gecko-template.apk" "$WORK/aligned.apk"

echo "== done =="
ls -la "$GT/gecko-template.apk"
"$BT/apksigner" verify --verbose "$GT/gecko-template.apk" | head -6
"$BT/aapt2" dump badging "$GT/gecko-template.apk" | head -4
